"""Produce a source-linked account directory and focused design-channel comparison."""
from pathlib import Path
from html import escape as e
import json

OUT=Path(__file__).resolve().parent
accounts=json.loads((OUT/'account-names.json').read_text())['accounts']
platforms=[
 {'name':'Wescover','url':'https://www.wescover.com/creator/boldstone','role':'Creator marketplace and design sourcing','verified':'Boldstone already has a public creator profile with sculpture listings. Wescover offers custom and commission pieces and a trade programme for design professionals.','fit':'The most immediate existing specialised presence to maintain: the Boldstone creator catalogue is already populated and is linked from the Instagram bio.','format':'Creator products, commission options and installed-work photography with accurate specifications.','gate':'Verify account management access and listing details before making updates; current access was not tested.','priority':'First existing specialised channel'},
 {'name':'Archilovers','url':'https://www.archilovers.com/','role':'Projects and professional network','verified':'Its public service supports project portfolios, photos, stories and product tagging for architecture and interior design.','fit':'Closest to Houzz for publishing completed installations and showing how sculpture works in a designed space.','format':'Project story with installation photographs, designer credits, location and materials.','gate':'Check the appropriate maker/business profile and publishing permissions before adding automation.','priority':'First for project publishing'},
 {'name':'Archiproducts','url':'https://business.archiproducts.com/en/','role':'Product catalogue and specification','verified':'Brand product sheets support photographs, descriptions, PDF catalogues, BIM/3D files and direct professional enquiry forms; products can connect to Archilovers projects.','fit':'Strong fit for repeatable wall panels, available finishes and pieces that interior designers can specify.','format':'Structured product listing with dimensions, materials, finishes, mounting, lead time and enquiry link.','gate':'Brand listing/onboarding and commercial terms require confirmation.','priority':'First for product discovery'},
 {'name':'Architonic','url':'https://www.architonic.com/en/about-us','role':'Curated product and materials library','verified':'A design-specification workspace with vetted brands, curated products and tools to compare and save products in projects.','fit':'Useful for architect and designer specification of architectural reliefs, wall panels and finishes.','format':'Curated technical product records and contextual project photography.','gate':'Brand approval and listing terms; inclusion for Boldstone has not been confirmed.','priority':'Consider after the specification pack'},
 {'name':'1stDibs','url':'https://www.1stdibs.com/dealer/application-form/?allowUniversalLink=no','role':'Curated design and art marketplace','verified':'The seller programme targets collectors and interior designers, includes fine art and sculptures, and selects sellers; a separate trade programme serves interior design firms.','fit':'Potential channel for higher-value sculpture and collectible design.','format':'Sale listing with precise condition, provenance, dimensions, pricing, availability and shipping.','gate':'Seller approval, fees, trade margin and fulfilment terms; no Boldstone seller account was verified.','priority':'Selective sales option'}
]
(OUT/'platform-comparison.json').write_text(json.dumps({'checked_date':'2026-11-23','baseline':'Houzz','platforms':platforms},ensure_ascii=False,indent=2)+'\n')

def link(url,label):return '<a href="'+e(url,quote=True)+'">'+e(label)+'</a>'
rows=[]
for a in accounts:
 username='No public @handle; location '+a['location_id'] if a['username'] is None else ('@'+a['username'] if a['platform'] in {'Instagram','Threads','X'} else a['username'])
 status='Activity confirmed' if a['status']=='verified' else 'Recent activity unconfirmed'
 activity=e(a['activity'])
 if a.get('activity_url'):activity+=' '+link(a['activity_url'],'View activity')
 rows.append('<tr><th scope="row">'+e(a['platform'])+'</th><td>'+e(a['display_name'])+'<br><small>'+e(username)+'</small></td><td>'+link(a['url'],'Open profile')+'</td><td><span class="badge '+('ok' if a['status']=='verified' else 'review')+'">'+e(status)+'</span><p>'+activity+'</p></td></tr>')
comparison=[]
for p in platforms:
 comparison.append('<tr><th scope="row">'+link(p['url'],p['name'])+'<br><small>'+e(p['role'])+'</small></th><td>'+e(p['fit'])+'</td><td>'+e(p['format'])+'</td><td>'+e(p['gate'])+'<br><strong>'+e(p['priority'])+'</strong></td></tr>')
sources=[]
for a in accounts:
 sources.append('<li>'+link(a['url'],a['platform']+' profile')+' — '+e(a['evidence'])+' '+link(a['evidence_file'],'Local evidence')+'</li>')
for p in platforms:
 sources.append('<li>'+link(p['url'],p['name']+' official service description')+' — '+e(p['verified'])+'</li>')
sources.append('<li>'+link('https://www.1stdibs.com/trade/apply/registration/','1stDibs trade programme')+' — confirms that the buyer programme serves interior design firms.</li>')
body='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Boldstone | Accounts and interior design platforms</title>
<style>
:root{color-scheme:light;--ink:#20302d;--muted:#596963;--line:#d8dfda;--paper:#f6f4ed;--green:#285845;--gold:#e9d7ac}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header,main,footer{max-width:1220px;margin:auto;padding:30px 32px}header{padding-top:48px;padding-bottom:22px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:.15em;text-transform:uppercase;color:var(--green)}h1{font-size:clamp(30px,4vw,46px);line-height:1.15;max-width:850px;letter-spacing:-.025em;margin:12px 0 20px}h2{font-size:27px;line-height:1.2;margin:0 0 18px}h3{margin:0 0 8px;font-size:18px}p{margin:0 0 15px}.lead{max-width:850px;color:var(--muted);font-size:18px}nav{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}nav a{padding:9px 16px;border:1px solid var(--line);border-radius:25px;background:white;text-decoration:none;font-weight:650}a{color:var(--green);text-underline-offset:3px}a:focus-visible{outline:3px solid #b78d32;outline-offset:4px}section{scroll-margin-top:20px;margin:0 0 42px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:22px 0}.card,.note{padding:22px;border:1px solid var(--line);border-radius:14px;background:#fff}.card p:last-child,.note p:last-child{margin-bottom:0}.note{border-left:5px solid var(--green)}.tablewrap{overflow-x:auto;border:1px solid var(--line);border-radius:14px;background:white}table{width:100%;border-collapse:collapse;text-align:left}thead{background:#e9eee9}th,td{padding:17px 18px;vertical-align:top;border-bottom:1px solid var(--line)}tbody tr:last-child>*{border-bottom:0}tbody th{width:16%;font-weight:700}td p{margin:9px 0 0}small{font-size:13px;font-weight:450;color:var(--muted)}.badge{display:inline-block;font-size:12px;font-weight:700;padding:3px 9px;border-radius:20px;white-space:nowrap}.ok{background:#e4f0e7;color:#205338}.review{background:#fff0ce;color:#72551b}.sources{font-size:14px;columns:2;column-gap:40px;padding-left:20px}.sources li{break-inside:avoid;margin-bottom:15px}ol.steps{padding-left:24px;max-width:950px}.steps li{padding:0 0 14px 6px}footer{border-top:1px solid var(--line);font-size:13px;color:var(--muted);padding-top:20px;padding-bottom:40px}@media(max-width:760px){header,main,footer{padding-left:18px;padding-right:18px}.cards{grid-template-columns:1fr}.sources{columns:1}th,td{padding:13px}table{min-width:760px}}@media print{body{background:#fff}header,main,footer{max-width:none;padding:20px 0}nav{display:none}.tablewrap{overflow:visible}table{min-width:0}a{color:inherit}section{break-inside:auto}.sources{columns:1}.card{break-inside:avoid}}
</style></head><body>
<header><div class="eyebrow">Boldstone Sculpture · Checked 23 November 2026</div><h1>Accounts and platforms for the interior design audience</h1><p class="lead">The existing social accounts are matched to Boldstone or Sally Price. For the next specialised channels, maintain the existing Wescover catalogue, then prioritise Archilovers for project stories and Archiproducts for product discovery and specification.</p><nav aria-label="Report sections"><a href="#overview">Overview</a><a href="#competitors">Competitors</a><a href="#guidance">Guidance</a><a href="#sources">Sources</a></nav></header>
<main><section id="overview"><h2>Overview</h2><p>This comparison uses Houzz as the reference channel, not as a competitor to Boldstone. Boldstone's official website describes work with interior and garden designers and architects; its own social links provide the starting identity match.</p><div class="cards"><div class="card"><h3>Six active accounts confirmed</h3><p>Facebook, Instagram, Threads, X, LinkedIn and Google have dated or native publication evidence. Evidence dates vary and are shown below.</p></div><div class="card"><h3>Houzz profile found</h3><p>The Sally-based address belongs to <strong>Boldstone Sculpture</strong>. One Ideabook is visible, but recent activity is unconfirmed.</p></div><div class="card"><h3>Existing Wescover catalogue</h3><p>Boldstone already has populated sculpture listings on Wescover, linked from Instagram. Archilovers and Archiproducts are the next two routes to assess.</p></div></div><h3>Account directory</h3><div class="tablewrap"><table><thead><tr><th scope="col">Platform</th><th scope="col">Account name / handle</th><th scope="col">Link</th><th scope="col">Activity evidence</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p style="margin-top:16px"><small>Facebook and Instagram evidence comes from verified publication receipts dated 19–20 November. Threads was read from the live signed-in profile on 23 November. X and Houzz were fetched from their live public pages today. LinkedIn and Google were checked in signed-in native pages today. These are account identifiers, not login credentials.</small></p></section>
<section id="competitors"><h2>Competitors: five alternatives to Houzz</h2><p>Platform features below are documented by the platforms. The Boldstone fit and order of preference are recommendations, not measured lead-generation results.</p><div class="tablewrap"><table><thead><tr><th scope="col">Platform / audience route</th><th scope="col">Why it fits Boldstone</th><th scope="col">Content to prepare</th><th scope="col">Entry condition / priority</th></tr></thead><tbody>'''+''.join(comparison)+'''</tbody></table></div><div class="note" style="margin-top:20px"><p><strong>Publishing format matters.</strong> Houzz and Archilovers suit visual project portfolios. Wescover needs creator product and commission listings. Archiproducts and Architonic need product/specification records; 1stDibs needs sale listings. Existing sculpture photos and descriptions can be reused, but a social-post script cannot be assumed to publish successfully to all five without separate account and format checks.</p></div></section>
<section id="guidance"><h2>Guidance</h2><ol class="steps"><li><strong>Maintain the existing Wescover catalogue.</strong> The creator is Boldstone at <code>/creator/boldstone</code>, with public sculpture listings, including pieces in this posting batch. Verify management access and listing details before making changes.</li><li><strong>Use the existing Houzz identity.</strong> The profile is Boldstone Sculpture under <code>sally-price2</code>. Confirm management access and inspect its one Ideabook before planning updates; no recent public activity was established.</li><li><strong>Prepare a project story for Houzz and Archilovers.</strong> Use an actual installed sculpture, contextual and detail photographs, accurate dimensions, finish, installation context and designer/photographer credits where applicable.</li><li><strong>Prepare a specification pack for Archiproducts.</strong> For a small set of reliable products, assemble dimensions, material, finish options, mounting details, lead times and an enquiry or purchase destination. Carry the same data into any later Architonic assessment.</li><li><strong>Assess 1stDibs selectively.</strong> Review seller eligibility and the economics of fees, trade pricing and delivery before deciding whether to apply.</li></ol><p>The existing Wescover profile was inspected, not updated. No accounts were created, applications submitted, commercial terms accepted or publications made to these five alternatives or Houzz during this review. The separately authorised LinkedIn and Google batch has its own publication records.</p><p><strong>Smallest remaining evidence gap:</strong> recent activity and management access on Houzz. X's Sally-based identity meets the requested activity condition: the public profile has a recent sculpture post and reciprocal Boldstone links.</p></section>
<section id="sources"><h2>Sources</h2><p>Public source checks were made on 23 November 2026. Platform pages establish their stated features, not comparative conversion rates. No audience-size ranking or promised sales outcome is inferred. Paid package prices and management access or onboarding on the five alternatives have not been verified.</p><ul class="sources">'''+''.join(sources)+'''<li>'''+link('https://boldstonesculpture.com/about','Boldstone official website and profile links')+''' — business context and reciprocal account links. '''+link('website-public-page.json','Local public-page extract')+'''</li><li>'''+link('publication-activity-summary.json','Local publication activity summary')+''' — counts and latest verification timestamps from existing receipts.</li></ul><p>'''+link('account-names.json','Download the seven-account directory (JSON)')+''' · '''+link('platform-comparison.json','Download the five-platform comparison (JSON)')+'''</p></section></main><footer>Prepared for Boldstone Sculpture. Public identities are verified separately from recent activity, management access and publication outcomes.</footer></body></html>'''
path=OUT/'boldstone-accounts-and-design-platforms-20261123.html';path.write_text(body,encoding='utf-8')
assert all('id="'+x+'"' in path.read_text() for x in ['overview','competitors','guidance','sources'])
assert '<style>' in body and body.count('<tbody>')==2 and len(platforms)==5 and len(accounts)==7
print(path.resolve())
